style.css:
@-moz-document domain("youtube.com") {
:root {
  --my-cream: #f5efdf;
  --my-paper: #fffaf0;
  --my-brown: #75614b;
  --my-dark: #30251e;
  --my-dot: #76624c;
}

/* polka dot edges */
ytd-app {
  background-color: var(--my-cream) !important;
  background-image:
    linear-gradient(var(--my-cream), var(--my-cream)),
    radial-gradient(circle, var(--my-dot) 2px, transparent 2.5px),
    radial-gradient(circle, var(--my-dot) 2px, transparent 2.5px) !important;
  background-size:
    calc(100% - 240px) 100%,
    28px 28px,
    28px 28px !important;
  background-position:
    center, left top, right top !important;
  background-repeat:
    no-repeat, repeat, repeat !important;
}

/* header */
#masthead-container {
  background-color: var(--my-paper) !important;
  border-bottom: 3px solid var(--my-brown) !important;
}

/* sidebar */
ytd-guide-renderer {
  background: var(--my-cream) !important;
}

/* video cards */
ytd-rich-item-renderer,
ytd-video-renderer {
  border-radius: 16px !important;
}

/* thumbnails */
ytd-thumbnail {
  border-radius: 13px !important;
  overflow: hidden !important;
}

/* video titles */
#video-title,
.title {
  color: var(--my-dark) !important;
}

/* search bar */
#container.ytd-searchbox {
  background: var(--my-paper) !important;
  border: 1px solid #d5c6ac !important;
  border-radius: 20px !important;
}

/* buttons */
ytd-button-renderer,
yt-button-shape {
  border-radius: 20px !important;
}
}
